//! Weapon reach and effect patterns by `classType`, generated from the weapon
//! subclass constructors in gorky17.exe (factory 0x4b4c00, pattern writer
//! 0x4b6340).
//!
//! A ray is `{dx, dy, chain, effect, pct}` (5 bytes at object +0x3a8): tile
//! relative to the shooter; `chain` continues the previous ray (does not pass
//! obstacles); `effect` is the index of the hit tile set; `pct` is the damage
//! percent at that range. A marker (`chain = 0xFF`) gives the side of the
//! second ray tile for wide (2×2) fighters.
//! Do not edit by hand.

const Ray = struct {
    dx: i8,
    dy: i8,
    kind: Kind,
    effect: u8,
    pct: u8,

    const Kind = enum { start, chain, side_x, side_y };
};

pub const Weapon = struct {
    class: u16,
    /// Mode 2 (+0x1a64): two-tile-wide ray (weapons of 2×2 fighters).
    wide: bool,
    rays: []const Ray,
    /// Hit tile sets relative to the target tile (+0x1734, up to 4).
    effects: [4][]const [2]i8,
};

pub fn find(class: i32) ?*const Weapon {
    for (&all) |*w| if (w.class == class) return w;
    return null;
}

